import { execSync } from 'node:child_process'
// Assembles the per-platform binding packages from the prebuilt artifacts of
// the `native build` workflow. Requires NAPI_PREBUILT_DIR to hold
// `binding.<suffix>.node` for every native target plus the wasm `binding.*`
// set, and produces:
//
// - npm/<suffix>/ — generated by `napi create-npm-dirs`, one .node each
// - npm/wasm/ — the checked-in manifest + the wasm artifacts
// - optionalDependencies pinning the eight native packages to the root
//   version (they auto-install on matching platforms only) and a
//   peerDependencies entry pinning @petrea/wasm, so the batch publishes as
//   one release while the wasm stack stays an opt-in install
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const prebuilt = process.env.NAPI_PREBUILT_DIR
if (!prebuilt) {
  throw new Error('NAPI_PREBUILT_DIR must point at the native build artifacts')
}

const nativeSuffixes = [
  'darwin-arm64',
  'darwin-x64',
  'linux-arm64-gnu',
  'linux-arm64-musl',
  'linux-x64-gnu',
  'linux-x64-musl',
  'win32-arm64-msvc',
  'win32-x64-msvc',
]
const wasmPkg = 'npm/wasm'

function main() {
  const present = new Set(readdirSync(prebuilt))

  // napi's create-npm-dirs reconciles npm/ against napi.targets and deletes
  // any binding manifest it does not manage — including the wasm package's,
  // whose artifacts are assembled by this script instead. Capture it before
  // generation and restore it right after.
  const wasmManifestPath = join(root, wasmPkg, 'package.json')
  const wasmManifestSource = readFileSync(wasmManifestPath, 'utf8')

  // generate the per-platform manifests (reads the napi config from the root
  // package.json, so versions inside match the release)
  execSync(
    'pnpm exec napi create-npm-dirs --cwd . --package-json-path package.json --npm-dir npm',
    { cwd: root, stdio: 'inherit' },
  )

  const { version } = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
  const wasmManifest = JSON.parse(wasmManifestSource)
  wasmManifest.version = version
  // when the wasm dir holds nothing else (a clean checkout without pnpm's
  // per-package node_modules), create-npm-dirs removes the emptied directory
  // along with the manifest
  mkdirSync(dirname(wasmManifestPath), { recursive: true })
  writeFileSync(wasmManifestPath, `${JSON.stringify(wasmManifest, null, 2)}\n`)

  for (const suffix of nativeSuffixes) {
    const file = `binding.${suffix}.node`
    if (!present.has(file)) {
      throw new Error(`NAPI_PREBUILT_DIR is missing the native binary: ${file}`)
    }
    cpSync(join(prebuilt, file), join(root, `npm/${suffix}`, file))
  }

  // the wasm set is every binding.* artifact that is not a native .node
  const wasmFiles = [...present].filter(
    file => file.startsWith('binding.') && !file.endsWith('.node'),
  )
  for (const file of wasmFiles) {
    cpSync(join(prebuilt, file), join(root, wasmPkg, file))
  }

  syncManifests(wasmManifest)
  writeDependencyVersions()
}

function syncManifests(wasmManifest) {
  // every binding package must be complete before anything publishes
  const incomplete = []
  for (const suffix of nativeSuffixes) {
    if (!existsSync(join(root, `npm/${suffix}/binding.${suffix}.node`))) {
      incomplete.push(`@petrea/binding-${suffix}`)
    }
  }
  for (const file of ['binding.wasm32-wasip1.wasm', 'binding.wasip1.cjs', 'binding.wasip1-browser.js']) {
    if (!existsSync(join(root, wasmPkg, file))) {
      incomplete.push(`${wasmManifest.name}:${file}`)
    }
  }
  if (incomplete.length > 0) {
    throw new Error(`incomplete binding packages: ${incomplete.join(', ')}`)
  }
}

function writeDependencyVersions() {
  const manifestPath = join(root, 'package.json')
  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
  // only the native bindings auto-install: os/cpu/libc filtering skips the
  // seven that do not match. @petrea/wasm installs everywhere by design, so
  // shipping it as an optionalDependency would put the wasm blob plus its
  // runtime deps (~4 MB) into every default install — hence the optional
  // peer instead, pinned to the root version so the batch publishes as one
  // release
  manifest.optionalDependencies = Object.fromEntries(
    nativeSuffixes.map(suffix => [`@petrea/binding-${suffix}`, manifest.version]),
  )
  manifest.peerDependencies = { '@petrea/wasm': manifest.version }
  // the workspace-only dev link must not leak into the published manifest:
  // npm publish does not strip devDependencies, and it cannot carry the
  // workspace: protocol
  delete manifest.devDependencies['@petrea/wasm']
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`)
}

main()
